nodes.statement:
We consider the $L^2$-critical generalized Korteweg--de Vries equation (gKdV) 
\begin{equation} {\rm (gKdV)}\quad  \left\{\begin{array}{ll}
 u_t + (u_{xx} + u^5)_x =0, \quad & (t,x)\in [0,T)\times {\mathbb R}, \\
 u(0,x)= u_0(x), & x\in {\mathbb R}.
\end{array}
\right.
\end{equation}

In particular, from a  rigidity theorem around solitons (\cite{MMjmpa}),  the first  proof of blow up in finite or infinite time was obtained (\cite{Mjams}) for 
initial data 
\begin{equation}\hbox {$u_0 \in H^1$ such that \eqref{utwosmall} and  $E(u_0)<0$.} \end{equation}

\noindent{\bf Minimal mass blow up solution  {\rm (\cite{MMR2}, \cite{MMduke})}.} 
{\it {\rm (i) Existence.} There exists a solution $S(t)\in \mathcal C((0,+\infty),H^1)$  to {\rm (\ref{kdv})} with minimal mass $\|S(t)\|_{L^2}=\|Q\|_{L^2}$ such that  
 \begin{equation} \|  S_x(t)\|_{L^2}\sim \frac{\|Q'\|_{L^2}}{ t}\ \ \mbox{as} \  t\downarrow 0.
 \end{equation}  \\
{\rm  (ii) Uniqueness.}
Let $u$ be an $H^1$  blow up solution to \eqref{kdv}  with minimal mass $\|u(t)\|_{L^2} = \|Q\|_{L^2}$. Then $u=S$ up to the invariances of the (gKdV) equation.

More precisely, let
$$
\mathcal{A}=
\left\{
u_0=Q+\varepsilon_0   \hbox{ with } \|\varepsilon_0\|_{H^1}<\alpha_0 \hbox{ and }
\int_{y>0} y^{10}\varepsilon_0^2< 1
\right\},
$$
$$\mathcal T_{\alpha^*}=\left\{u\in H^1\ \ \mbox{with}\ \ \inf_{\lambda_0>0, \, x_0\in \mathbb{R}}
\left\|u- Q_{\lambda_0}\left( .-x_0 \right) \right\|_{L^2} <\alpha^*\right\}.$$

conclusions:
there exists $u \in  C((0,T_0],H^1)$   solution  of \eqref{kdv} blowing up at $t=0$ with
\begin{equation}\label{th:1:1}
\|u_x(t)\|_{L^2} \sim t^{-\nu}\ \ \mbox{as}\ \ t\downarrow 0^+.\end{equation}

there exists  $u\in  C([T_0,+\infty),H^1)$ solution of \eqref{kdv} growing  up at $ +\infty$ with
\begin{equation}\label{th:1:4}
\|u_x(t)\|_{L^2} \sim e^{t} \ \ \mbox{as}\ \ t\to +\infty.
\end{equation}

there exists  $u\in  C([0,+\infty),H^1)$ solution of \eqref{kdv} growing  up at $ +\infty$ with
\begin{equation}\label{th:1:5}
\|u_x(t)\|_{L^2} \sim t^{\nu}\ \ \mbox{as}\ \ t\to +\infty.
\end{equation}

there exists $u \in  C((0,T_0],H^1)$   solution  of \eqref{kdv} blowing up at $t=0$ with
\begin{equation}\label{th:1:1}
\|u_x(t)\|_{L^2} \sim t^{-\nu}\ \ \mbox{as}\ \ t\downarrow 0^+.\end{equation}

there exists  $u\in  C([T_0,+\infty),H^1)$ solution of \eqref{kdv} growing  up at $ +\infty$ with
\begin{equation}\label{th:1:4}
\|u_x(t)\|_{L^2} \sim e^{t} \ \ \mbox{as}\ \ t\to +\infty.
\end{equation}

there exists  $u\in  C([0,+\infty),H^1)$ solution of \eqref{kdv} growing  up at $ +\infty$ with
\begin{equation}\label{th:1:5}
\|u_x(t)\|_{L^2} \sim t^{\nu}\ \ \mbox{as}\ \ t\to +\infty.
\end{equation}

nodes.statement:
We let the linearized operator close to the ground state be:
\begin{equation} Lf=-f''+f-5Q^4f.
\end{equation}

conclusions:
There exists a unique $Y_0\in \mathcal Y$, even, such that
\begin{equation} \label{YQ}
L Y_0= 5  Q^4 ,\quad
(Q,Y_0)=-\frac 34 \int Q  .
\end{equation}

There exists a unique function $P$ such that $P' \in \mathcal{Y}$ and
\begin{equation}
\label{eq:23}
 (L  P)'={\Lambda} Q, \ \  \mathop{\rm lim}_{y \to -\infty}   P(y) = \frac 12 \int Q,  \ \ \mathop{\rm lim}_{y \to +\infty}   P(y) =0,
 \end{equation}
 \begin{equation}
 \label{PQ}
 (P, Q) = \frac 1{16} \left(\int Q\right)^2 > 0,\quad (P,  Q')=0.
 \end{equation}

{\rm (i) Estimates on $Q_b$:} For all $y \in \mathbb{R}$,
\begin{align}
&	|Q_b(y)|\lesssim  e^{-|y|} + |b| \left(  {\mathbf{1}}_{[-2,0]}(|b|^\gamma y) +  e^{-\frac {|y|}{2}} \right),
\label{eq:001}\\
&	|Q_b^{(k)}(y)|\lesssim  e^{-|y|} +   |b|  e^{-\frac {|y|}{2}} +|b|^{1+k \gamma} {\mathbf{1}}_{[-2,-1]}(|b|^\gamma y),\quad  \text{for $k\geq 1$}.
\label{eq:002}
\end{align}

