nodes.statement:
We first claim the strict outgoing behavior:
\begin{equation} H'(s^*)\geq \frac {1}{20 s^*}.
\end{equation}

{\bf step 2} Equation of $\varepsilon$ and a priori bounds. To write the equation of $\varepsilon$, we first derive the equation of $w$ from the equations of $u(t)$ and $q_0(t)$:
 \begin{equation} w_t + (w_{xx} + w^5)_x = - (W_0)_x,
 \end{equation}
 where
 \begin{equation} W_0 = 5 w^4 q_0 + 10 w^3 q_0^2 + 10w^2 q_0^3 + 5w q_0^4.
  \end{equation}

{\bf step 4} Modulation equations. We argue as in \cite{MMR1}, proof of Lemma 2.7, differentiating with respect to $s$ the orthogonality conditions $\int \varepsilon \Lambda Q=0$, $\int \varepsilon Q'=0$ and 
$\int \varepsilon Q=0$ and using \eqref{eqofeps} to obtain   \eqref{eq:2002bis}
and \eqref{eq:2003}.
Here, we  will  treat only  the   terms  coming from $q$ and $pY_0$ in \eqref{eqofeps} and we refer the reader to \cite{MMR1} for more details on the other terms.
\medskip


\emph{Proof of   \eqref{eq:2002bis} and \eqref{eq:2003}.} 
It follows from computations in \cite{MMR1} proof of Lemma~2.7 and Claim \ref{cl:one} that
\begin{align*}
& \left| \left( {\frac{{\lambda}_s}{{\lambda}}} + {b} \right) -  \frac {( \varepsilon,L(\Lambda Q)')}{\|\Lambda Q\|_{L^2}^2}  \right|  
 \\ & \lesssim 
 \left( \left|  {\frac{{\lambda}_s}{{\lambda}}}+ {b}  \right|  +|b|\right)\left(|p|+ |b|  + \left( \int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} \right)  + |p| \left( \int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} \\
 & + \left| {\frac{x_s}{{\lambda}}} - 1 \right| \left(  |b|  + \left( \int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} \right)
 +|p_s|+|{b}_{s}|+\int \varepsilon^2 e^{-\frac{|y|}{10}} + p^8    +
 \frac {\lambda}{x} |p|   .
\end{align*}

We proceed similarly for $\frac{x_s}{\lambda}-1$, taking into account different cancellations due to parity properties \begin{align*}
&  \left|\left( {\frac{x_s}{{\lambda}}} - 1  \right) - \frac {( \varepsilon,L(y \Lambda Q)')}{\|\Lambda Q\|_{L^2}^2}  \right|
 \\ & \lesssim 
 \left( \left|  {\frac{{\lambda}_s}{{\lambda}}}+ {b}  \right| + \left| {\frac{x_s}{{\lambda}}} - 1 \right|  +|b|\right)\left(|p|+|b|  + \left( \int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} \right) 
 \\ &+|{b}_{s}|+\int \varepsilon^2 e^{-\frac{|y|}{10}} 
   +p^2 +\frac \lambda x |p|.
\end{align*}

Then, taking the scalar product of \eqref{eqofeps} by $Q$ and arguing similarly, we have the following 
rough estimate for $b_s$:
\begin{align*}
|{b}_{s}| &\lesssim  \left| {\frac{{\lambda}_s}{{\lambda}}} + {b}\right|^2 + \left| {\frac{x_s}{{\lambda}}} - 1 \right|^2 +  {|b|}^2 +  \int   \varepsilon^2   {e^{-\frac{|y|}{10}}} 
+ |p| \left( \int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12}
\\ &+|p_s| + |b| |p| +p^8
 +\frac \lambda x |p| .
\end{align*}

Combining these estimates with (from \eqref{cl.2bis})
$$
|p_s| \leq \left|   \frac{\lambda_s}{\lambda} \right| |p| + \frac {\lambda}{x}  |p|\left( \left|\frac{x_s}{\lambda} - 1\right| + 1 \right)
\leq |b| |p| +\left| \frac{\lambda_s}{\lambda}+b\right| |p| +  \frac \lambda x |p|\left( \left|\frac{x_s}{\lambda} - 1\right| + 1 \right),
$$
from \eqref{cl.2tri},
we obtain  \eqref{eq:2002bis} and \eqref{eq:2003}. 









\medskip

\emph{Proof of \eqref{fond}.}
First, we derive a refined equation for $b_s$, taking the scalar product of equation \eqref{eqofeps} by $Q$ and proceeding as   in \cite{MMR1},  proof of Lemma 2.7.

Recall from \cite{MMR1},
$$(\Psi_b,Q)= -\frac {b^2}{8} \|Q\|_{L^1}^2 + O(|b|^3),\quad  (\Phi_b, Q) = -\frac {b_s}{16} \|Q\|_{L^1}^2 +O(|b|^{10}).
$$
Note also that from direct computations and parity properties
\begin{align*}
&\left|\left( ((\varepsilon+pY_0 + Q_b)^5 - Q_b^5 - p5Q^4 Y_0 - 5Q^4 \varepsilon)_y,Q\right)
- 20 bp((Q^3Y_0 P )_y,Q) \right| \\
&+ \left| \left((\widetilde W)_y,Q\right)-20 bp (( P Q^3)_y,Q)\right|\\
& \lesssim  |b|^3 +|p|^3 + \int \varepsilon^2 {e^{-\frac{|y|}{10}}} 
+ (|p|+|b|) \left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} 
  .
\end{align*}
(See \cite{MMR1} for details on the nonlinear terms in $\varepsilon$.)
Using   \eqref{cl.4bis} and 
the above estimates
we find\begin{align}
&\bigg| b_s + 2b^2  - \frac {16}{(\int Q)^2} \bigg( -  p_s (Y_0,Q)  - \frac{\lambda_s}{\lambda} p 
 (Y_0,\Lambda Q)  \nonumber\\
&  -  bp \left[ 20 ((Q^3Y_0 P)_y,Q) + 20 ((PQ^3)_y,Q) \right]
 + c_0 \theta \left(\int Q\right) \lambda^{\frac 32}(s) x^{-\theta-1}(s) \bigg)\bigg|\\
& \lesssim |b|^3+  |p|^3 +\int \varepsilon^2 {e^{-\frac{|y|}{10}}} +(|p|+|b|) \left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} 
 +\frac {\lambda^2}{x^2} |p|+\frac {\lambda}{x^3} |p|. \end{align}

We claim  the following cancellation
\begin{equation} - (Y_0,\Lambda Q) + 20 ((Q^3Y_0 P)_y,Q) + 20 ((PQ^3)_y,Q) =0.
\end{equation}
Indeed, 
$L(P')= (LP)' + 20 Q^3 Q' P = \Lambda Q + 20 Q^3 Q' P,$
and so from \eqref{eq:23},
\begin{align*}
& - (Y_0,\Lambda Q) + 20 ((Q^3Y_0 P)_y,Q) + 20 ((PQ^3)_y,Q) 
\\ &= - (Y_0,\Lambda Q)-  20 (Y_0+1,PQ^3 Q')\\
& = - (Y_0+1 , L(P')) + \int \Lambda Q = - (L(Y_0+1),P') - \frac 12 \int Q
\\ & = - \int P' -  \frac 12 \int Q  =  P(-\infty) - \frac 12 \int Q =0.
\end{align*}
Thus,
\begin{align*}
& \left| 
 - \frac{\lambda_s}{\lambda} p 
 (Y_0,\Lambda Q) +  bp \left[ 20 ((Q^3Y_0 P)_y,Q) + 20 ((PQ^3)_y,Q) \right]
\right|  = 
|p| \left| \frac{\lambda_s}{\lambda}+b \right|  |(Y_0,\Lambda Q)|.
\end{align*}

\medskip

Now, from $(Y_0,Q) =- \frac 34 \int Q$ (see   \eqref{YQ}),
  using \eqref{cl.1bis} and \eqref{cl.2bis} we note that 
\begin{align}
& \frac {16}{(\int Q)^2} \bigg( -  p_s (Y_0,Q)+ c_0 \theta \left(\int Q\right) \lambda^{\frac 32}(s) x^{-\theta-1}(s) \bigg)\nonumber \\
& =   \frac {12}{(\int Q)} c_0 \lambda^{\frac 12} x^{-\theta}  \left(  \frac 12 \frac{\lambda_s}{\lambda} 
 +\frac \theta 3    \frac {x_s}{x}    \right) +O\left(\frac {\lambda}{x^{3}}| p|\right)  + O\left( \frac {\lambda}{x} |p| \left|\frac{x_s}{\lambda}-1\right|\right). \end{align}
Therefore, 
\begin{align}
&\bigg| b_s + 2b^2 - \frac {4}{(\int Q)} c_0 \lambda^{\frac 12} x^{-\theta}  \left(  \frac 32 \frac{\lambda_s}{\lambda} 
 +  \theta     \frac {x_s}{x}    \right)   \bigg| \nonumber \\
& \lesssim  |b|^3 +|p|^3 + \int \varepsilon^2 {e^{-\frac{|y|}{10}}} 
+ (|p|+|b|) \left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} +
\frac {\lambda^2}{x^2} |p| + \frac {\lambda}{x^3} |p|
. \end{align}


Now, we prove \eqref{fond}. By direct computation,
$$
\frac d{ds}\left( \frac 4{\left(\int Q\right)}c_0 \theta   \lambda^{-\frac 32}(s) x^{-\theta}\right) = - \frac {4}{(\int Q)} c_0 \lambda^{-\frac 32} x^{-\theta}  \left(  \frac 32 \frac{\lambda_s}{\lambda} 
 +  \theta     \frac {x_s}{x}    \right)  
$$
$$
\frac d{ds}\left( \frac b{\lambda^2}\right)
 =   \frac {b_s}{\lambda^2} - 2 \frac{\lambda_s}{\lambda} \frac b{\lambda^2}
 =   \frac {b_s}{\lambda^2}  + 2 \frac {b^2}{\lambda^2} - 2 \left( \frac{\lambda_s}{\lambda} +b\right) \frac b{\lambda^2}.$$
 and \eqref{fond} follows from \eqref{eq:b} and \eqref{eq:2002bis}.

